     1→import {ResponseOutgoing} from "@lodestar/reqresp";
     2→import {computeEpochAtSlot} from "@lodestar/state-transition";
     3→import {ColumnIndex} from "@lodestar/types";
     4→import {toRootHex} from "@lodestar/utils";
     5→import {IBeaconChain} from "../../../chain/index.js";
     6→import {IBeaconDb} from "../../../db/index.js";
     7→import {DataColumnSidecarsByRootRequest} from "../../../util/types.js";
     8→import {
     9→  handleColumnSidecarUnavailability,
    10→  validateRequestedDataColumns,
    11→} from "../utils/dataColumnResponseValidation.js";
    12→
    13→export async function* onDataColumnSidecarsByRoot(
    14→  requestBody: DataColumnSidecarsByRootRequest,
    15→  chain: IBeaconChain,
    16→  db: IBeaconDb
    17→): AsyncIterable<ResponseOutgoing> {
    18→  // SPEC: minimum_request_epoch = max(current_epoch - MIN_EPOCHS_FOR_DATA_COLUMN_SIDECARS_REQUESTS, FULU_FORK_EPOCH)
    19→  const currentEpoch = chain.clock.currentEpoch;
    20→  const minimumRequestEpoch = Math.max(
    21→    currentEpoch - chain.config.MIN_EPOCHS_FOR_DATA_COLUMN_SIDECARS_REQUESTS,
    22→    chain.config.FULU_FORK_EPOCH
    23→  );
    24→
    25→  for (const dataColumnsByRootIdentifier of requestBody) {
    26→    const {blockRoot, columns: requestedColumns} = dataColumnsByRootIdentifier;
    27→    const availableColumns = validateRequestedDataColumns(chain, requestedColumns);
    28→    if (availableColumns.length === 0) {
    29→      return;
    30→    }
    31→
    32→    const blockRootHex = toRootHex(blockRoot);
    33→    const block = chain.forkChoice.getBlockHex(blockRootHex);
    34→    // If the block is not in fork choice, it may be finalized. Attempt to find its slot in block archive
    35→    const slot = block ? block.slot : await db.blockArchive.getSlotByRoot(blockRoot);
    36→
    37→    if (slot === null) {
    38→      // We haven't seen the block
    39→      continue;
    40→    }
    41→
    42→    const requestedEpoch = computeEpochAtSlot(slot);
    43→
    44→    // SPEC: Clients MUST support requesting sidecars since minimum_request_epoch.
    45→    // If any root in the request content references a block earlier than minimum_request_epoch, peers MAY respond with
    46→    // error code 3: ResourceUnavailable or not include the data column sidecar in the response.
    47→    // https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.5/specs/fulu/p2p-interface.md#datacolumnsidecarsbyroot-v1
    48→    if (requestedEpoch < minimumRequestEpoch) {
    49→      continue;
    50→    }
    51→
    52→    const dataColumns = block
    53→      ? // Non-finalized sidecars are stored by block root
    54→        await db.dataColumnSidecar.getManyBinary(blockRoot, availableColumns)
    55→      : // Finalized sidecars are archived and stored by slot
    56→        await db.dataColumnSidecarArchive.getManyBinary(slot, availableColumns);
    57→
    58→    const unavailableColumnIndices: ColumnIndex[] = [];
    59→    for (let i = 0; i < dataColumns.length; i++) {
    60→      const dataColumnBytes = dataColumns[i];
    61→      if (dataColumnBytes) {
    62→        yield {
    63→          data: dataColumnBytes,
    64→          boundary: chain.config.getForkBoundaryAtEpoch(requestedEpoch),
    65→        };
    66→      }
    67→
    68→      // TODO: Check blobs for that block and respond resource_unavailable
    69→      // After we have consensus from other teams on the specs
    70→      else {
    71→        unavailableColumnIndices.push(availableColumns[i]);
    72→      }
    73→    }
    74→
    75→    if (unavailableColumnIndices.length) {
    76→      await handleColumnSidecarUnavailability({
    77→        chain,
    78→        db,
    79→        metrics: chain.metrics,
    80→        slot,
    81→        blockRoot,
    82→        unavailableColumnIndices,
    83→        requestedColumns,
    84→        availableColumns,
    85→      });
    86→    }
    87→  }
    88→}
